effect.shader:
vec4 fxPortOutput;

vec4 fxPortSample(sampler2D image, vec2 uv) {
    vec4 color = texture2D(image, uv);
    if (color.a > 0.0) color.rgb /= color.a;
    else color.rgb = vec3(0.0);
    return color;
}

void fxPortMain() {
    vec2 uv = clamp(acScreenNorm, 0.0, 1.0);
    vec4 original = fxPortSample(inputImg.texture, uv);
    float turns = 0.5 * uControl2;
    float angle = turns * 6.28318530718;
    vec2 normal = vec2(-sin(angle), cos(angle));
    vec2 center = vec2(0.5 + 0.25 * uControl3,
                       0.5 + 0.25 * uControl4);
    float side = dot(uv - center, normal);
    vec2 reflected = uv;
    if (side < 0.0) {
        reflected -= 2.0 * side * normal;
    }
    float inside = step(0.0, reflected.x) * step(reflected.x, 1.0) *
                   step(0.0, reflected.y) * step(reflected.y, 1.0);
    vec3 background = clamp(vec3(uControl5, uControl6, uControl7), 0.0, 1.0);
    vec3 sampled = fxPortSample(inputImg.texture, clamp(reflected, 0.0, 1.0)).rgb;
    vec3 effected = mix(background, sampled, inside);
    fxPortOutput = clamp(vec4(mix(original.rgb, effected,
                                   clamp(uControl1, 0.0, 1.0)), original.a),
                         0.0, 1.0);
}

void main() {
    fxPortMain();
    gl_FragColor = vec4(fxPortOutput.rgb * fxPortOutput.a, fxPortOutput.a);
}
